def _parse_money(value: str) -> Decimal:
    """The dollar amount on a line, ignoring notes that follow it."""
    # The amount is the first dollar figure ("Stop Off: $100.00 (1 extra stop)").
    # Trailing notes can contain bare numbers that are not money ("after 2 hrs").
    match = _MONEY.search(value)
    amount = match.group(1) if match else None
    if amount is None:
        # A few partner TMSes omit the dollar sign ("1800.00 USD").
        match = _NUMBER.search(value)
        if not match:
            raise RateConError(f"no amount in {value!r}")
        amount = match.group(0)
    return Decimal(amount.replace(",", ""))

